contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount) public {
        require(to != address(0));
        require(from != address(0));

        // setup: gives the test contract a balance from `from` so transferFrom can succeed if allowance is sufficient
        // (does not depend on from's own balance; only on allowance, so we must be whitelisted to getTokens)
        c.getTokens();

        // before values: the test contract is msg.sender; we measure allowance from -> msg.sender
        uint256 beforeAllowance = c.allowance(from, address(this));

        // make the deciding call: transferFrom(from, to, amount)
        // if the allowance is insufficient, this call will revert at the require and not modify state
        bool reverted;
        try c.transferFrom(from, to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // after value: allowance from -> msg.sender after the call
        uint256 afterAllowance = c.allowance(from, address(this));

        // General rule:
        // - if the transferFrom executed, then either it reverted (and allowance is unchanged) or it succeeded
        //   and the allowance decreased by exactly `amount`.
        // - if the allowance was insufficient (< amount), the call must have reverted and allowance is unchanged.
        assert(
            (reverted && beforeAllowance == afterAllowance) ||
            (!reverted && beforeAllowance >= amount && afterAllowance == beforeAllowance - amount)
        );
    }

    receive() external payable {}
}

