contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 burnValue) public payable {
        require(burnValue <= c.balanceOf(address(this)), "burn amount must not exceed owner balance");

        uint256 supplyBefore = c.totalSupply();
        uint256 ownerBalanceBefore = c.balanceOf(address(this));

        bool reverted;
        try c.burn(burnValue) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 ownerBalanceAfter = c.balanceOf(address(this));

        if (!reverted) {
            assert(supplyBefore == supplyAfter + burnValue);
            assert(ownerBalanceBefore == ownerBalanceAfter + burnValue);
        } else {
            assert(supplyAfter == supplyBefore);
            assert(ownerBalanceAfter == ownerBalanceBefore);
        }
    }
}

