    }

    function run(uint256 x) public payable {
        uint256 beforeTotalDistributed = c.totalDistributed();
        require(x <= beforeTotalDistributed);

        bool reverted;
        try c.burn(x) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotalDistributed = c.totalDistributed();
        if (msg.sender == address(this)) {
            assert(!reverted && afterTotalDistributed + x == beforeTotalDistributed);
        } else {
            assert(reverted && afterTotalDistributed == beforeTotalDistributed);
        }
    }

    receive() external payable {}
}

